// Simple application - Security Hardened Version
// Security improvements applied: input validation, error handling, security headers, rate limiting

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, param, validationResult } = require('express-validator');

const app = express();

// Trust proxy for secure deployment behind reverse proxies
app.set('trust proxy', 1);

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Request Logging
app.use(morgan('combined'));

// Body parsing with limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting for all requests
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 1000, // limit each IP to 1000 requests per windowMs
  message: { error: 'Too many requests from this IP' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limiting for API routes
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100, // stricter limit for API
  message: { error: 'Too many API requests from this IP' }
});

// Health check endpoint
app.get('/health', 
  [
    // This rule would apply if you add query params in the future
    query('check').optional().isIn(['full', 'basic']).escape()
  ],
  handleValidationErrors,
  (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  }
);

// Users endpoint with strict rate limiting
app.get('/users', apiLimiter, (req, res, next) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(users);
  } catch (error) {
    next(error);
  }
});

// Example endpoint with ID parameter validation (for future expansion)
app.get('/users/:id',
  apiLimiter,
  [
    param('id')
      .isInt({ min: 1, max: 1000000 })
      .withMessage('User ID must be a positive integer')
      .toInt()
  ],
  handleValidationErrors,
  (req, res) => {
    // Now req.params.id is validated and sanitized
    const userId = req.params.id;
    res.json({ id: userId, name: 'Example', email: 'example@example.com' });
  }
);

// Validation helper middleware
function handleValidationErrors(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      errors: errors.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }
  next();
}

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found', message: 'The requested resource does not exist' });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  // Log error for debugging (in production, use a proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'production' ? undefined : err.stack,
    ip: req.ip,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Don't leak error details in production
  const statusCode = err.statusCode || err.status || 500;
  res.status(statusCode).json({
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'production' 
      ? 'Something went wrong' 
      : err.message
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

