/**
 * Secure Express Application
 * Implements security best practices for error handling and input validation
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, param, validationResult } = require('express-validator');
const winston = require('winston');
const cors = require('cors');

// Configure structured logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'user-service' },
  transports: [
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

const app = express();

// Trust proxy settings - configure based on your deployment environment
app.set('trust proxy', 1);

// Security middleware: Helmet for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// CORS configuration - restrict to trusted origins in production
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400
};
app.use(cors(corsOptions));

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: {
    error: 'Too many requests, please try again later.',
    retryAfter: '15 minutes'
  },
  handler: (req, res, next, options) => {
    logger.warn(`Rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json(options.message);
  }
});
app.use(limiter);

// Stricter rate limit for sensitive endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: { error: 'Too many authentication attempts, please try again later.' }
});

// Request size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging middleware
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    path: req.path,
    ip: req.ip,
    userAgent: req.get('user-agent'),
    timestamp: new Date().toISOString()
  });
  next();
});

// ============ VALIDATION MIDDLEWARE ============

/**
 * Custom validation error handler
 * Sanitizes error messages to prevent information leakage
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation errors:', { 
      errors: errors.array(),
      ip: req.ip,
      path: req.path 
    });

    return res.status(400).json({
      error: 'Validation failed',
      // Only expose field names, not internal error details
      fields: errors.array().map(err => ({
        field: err.path,
        message: 'Invalid input'
      }))
    });
  }
  next();
};

/**
 * Async error wrapper - catches errors in async route handlers
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============ ROUTES ============

/**
 * Health check endpoint
 * Returns sanitized system status
 */
app.get('/health', 
  asyncHandler(async (req, res) => {
    const healthCheck = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      // Don't expose sensitive system details
      version: process.env.npm_package_version || '1.0.0'
    };

    res.json(healthCheck);
  })
);

/**
 * Users list endpoint
 * Returns paginated, filtered user data
 */
app.get('/users',
  // Input validation
  [
    param('page').optional().isInt({ min: 1, max: 1000 }).toInt(),
    param('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    param('search').optional().trim().escape().isLength({ max: 100 }),
    handleValidationErrors
  ],
  asyncHandler(async (req, res) => {
    const page = req.query.page || 1;
    const limit = Math.min(req.query.limit || 10, 100);
    const search = req.query.search || '';

    // In production, this would query a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter users if search parameter provided
    const filteredUsers = search 
      ? users.filter(u => 
          u.name.toLowerCase().includes(search.toLowerCase()) ||
          u.email.toLowerCase().includes(search.toLowerCase())
        )
      : users;

    // Implement pagination
    const startIndex = (page - 1) * limit;
    const paginatedUsers = filteredUsers.slice(startIndex, startIndex + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: filteredUsers.length,
        totalPages: Math.ceil(filteredUsers.length / limit)
      }
    });
  })
);

/**
 * Get user by ID
 * Validates and sanitizes ID parameter
 */
app.get('/users/:id',
  // Input validation for ID parameter
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('ID must be a positive integer')
      .toInt(),
    handleValidationErrors
  ],
  asyncHandler(async (req, res) => {
    const userId = req.params.id;

    // Simulate database lookup with parameterized query concept
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      logger.warn('User not found', { userId, ip: req.ip });
      return res.status(404).json({ error: 'User not found' });
    }

    res.json({ data: user });
  })
);

/**
 * Create user endpoint (example of POST with validation)
 * Demonstrates comprehensive input validation
 */
app.post('/users',
  authLimiter, // Apply stricter rate limiting
  [
    body('name')
      .trim()
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 100 }).withMessage('Name must be between 2 and 100 characters')
      .matches(/^[a-zA-Z\s'-]+$/).withMessage('Name contains invalid characters')
      .escape(),
    body('email')
      .trim()
      .notEmpty().withMessage('Email is required')
      .isEmail().withMessage('Invalid email format')
      .normalizeEmail()
      .isLength({ max: 254 }).withMessage('Email too long'),
    body('age')
      .optional()
      .isInt({ min: 13, max: 120 }).withMessage('Age must be between 13 and 120'),
    handleValidationErrors
  ],
  asyncHandler(async (req, res) => {
    const { name, email, age } = req.body;

    // In production: check for duplicate email before creating
    logger.info('Creating new user', { email: email.substring(0, 3) + '***' });

    const newUser = {
      id: Date.now(), // In production, use UUID or database auto-increment
      name,
      email,
      age,
      createdAt: new Date().toISOString()
    };

    res.status(201).json({
      message: 'User created successfully',
      data: newUser
    });
  })
);

// ============ ERROR HANDLING ============

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  logger.warn('Route not found', { 
    method: req.method, 
    path: req.path,
    ip: req.ip 
  });
  res.status(404).json({ error: 'Resource not found' });
});

/**
 * Global error handler
 * Catches all errors and prevents information leakage
 */
app.use((err, req, res, next) => {
  logger.error('Unhandled error:', {
    error: err.message,
    stack: err.stack,
    method: req.method,
    path: req.path,
    ip: req.ip
  });

  // Don't expose error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: 'Internal server error',
    ...(isDevelopment && { message: err.message, stack: err.stack })
  });
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, shutting down gracefully');
  process.exit(0);
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  logger.error('Uncaught Exception:', err);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

// Start server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = { app, server };

/**
 * Security Test Suite
 * Tests for input validation, error handling, and security headers
 */

const request = require('supertest');
const { app } = require('./app-secure');

describe('Security Tests', () => {
  describe('Input Validation', () => {
    test('should reject invalid user ID (negative number)', async () => {
      const response = await request(app)
        .get('/users/-1')
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
    });

    test('should reject invalid user ID (string)', async () => {
